import { defineCollection } from 'astro:content';
import { glob } from 'astro/loaders';
import { z } from 'astro/zod';
import { articleTypes, author, categories } from './site.config.ts';

/**
 * Content schema for TekkTech.
 *
 * Every article in src/content/articles/ is validated against this schema at
 * build time. An invalid article stops the build with a clear error, so a
 * broken article can never be deployed.
 *
 * The CMS (public/admin, generated by scripts/prepare-admin.ts) writes the
 * same fields. If you add a field here, add it to scripts/cms-config.ts too.
 */

export const SLUG_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

/** Slugs that would collide with listing routes. */
export const RESERVED_SLUGS = ['page', 'feed', 'rss', 'index', 'admin', 'search', 'preview'];

const categorySlugs = categories.map((category) => category.slug) as [string, ...string[]];
const typeValues = articleTypes.map((type) => type.value) as [string, ...string[]];

/** The CMS writes empty optional fields as "" or null; treat those as absent. */
const blankToUndefined = (value: unknown) =>
  value === '' || value === null || (Array.isArray(value) && value.length === 0) ? undefined : value;

const optionalText = z.preprocess(blankToUndefined, z.string().trim().optional());
const optionalUrl = z.preprocess(blankToUndefined, z.url({ protocol: /^https?$/ }).optional());
const optionalDate = z.preprocess(blankToUndefined, z.coerce.date().optional());
const textList = z.preprocess(
  (value) => (value === null || value === '' ? [] : value),
  z.array(z.string().trim().min(1)).default([]),
);

const sourceSchema = z.object({
  title: z.string().trim().min(1, 'Every source needs a title'),
  url: z.url({ protocol: /^https?$/, error: 'Source URLs must start with http:// or https://' }),
  publisher: optionalText,
  note: optionalText,
});

const linkSchema = z.object({
  label: z.string().trim().min(1),
  url: z.url({ protocol: /^https?$/ }),
  note: optionalText,
});

const affiliateLinkSchema = z.object({
  label: z.string().trim().min(1, 'Affiliate links need a label, e.g. "Check price at Retailer"'),
  url: z.url({ protocol: /^https?$/ }),
  retailer: optionalText,
});

const reviewSchema = z.object({
  productName: z.string().trim().min(1, 'Reviews need a product name'),
  productCategory: optionalText,
  summary: optionalText,
  /**
   * Optional score out of 10 (half points allowed). Only use it when the
   * product was assessed with the methodology on /how-we-review/.
   */
  score: z.preprocess(blankToUndefined, z.number().min(0).max(10).multipleOf(0.5).optional()),
  strengths: textList,
  weaknesses: textList,
  bestFor: optionalText,
  avoidIf: optionalText,
  methodology: optionalText,
  /**
   * True only if TekkTech genuinely used the product. Controls the wording
   * shown to readers and whether Review structured data is emitted.
   */
  handsOn: z.boolean().default(false),
  reviewDate: optionalDate,
  alternatives: z.preprocess((value) => value ?? [], z.array(linkSchema).default([])),
});

export type ReviewData = z.infer<typeof reviewSchema>;

/**
 * The CMS writes the collapsed "Review details" group as an object even for
 * non-review articles (e.g. `review: { handsOn: false }`). Treat a review
 * block without a product name as absent.
 */
const emptyReviewToUndefined = (value: unknown) => {
  const blank = blankToUndefined(value);
  if (blank && typeof blank === 'object' && !Array.isArray(blank)) {
    const name = (blank as { productName?: unknown }).productName;
    if (typeof name !== 'string' || name.trim() === '') return undefined;
  }
  return blank;
};

const articles = defineCollection({
  loader: glob({
    pattern: '**/*.md',
    base: './src/content/articles',
    // The file name is the article's permanent identifier. The public URL
    // comes from the `slug` field, which is validated for uniqueness in
    // src/lib/articles.ts.
    generateId: ({ entry }) => entry.replace(/\.md$/, ''),
  }),
  schema: ({ image }) =>
    z
      .object({
        title: z.string().trim().min(5, 'Titles should be at least 5 characters').max(120),
        slug: z
          .string()
          .trim()
          .regex(SLUG_PATTERN, 'Slugs may only contain lowercase letters, numbers and single hyphens')
          .refine((slug) => !RESERVED_SLUGS.includes(slug), 'This slug is reserved — choose another'),
        excerpt: z.string().trim().min(20).max(300),
        category: z.enum(categorySlugs),
        type: z.enum(typeValues).default('explainer'),
        tags: z.preprocess(
          (value) => (value === null || value === '' ? [] : value),
          z.array(z.string().trim().toLowerCase().min(1)).default([]),
        ),
        status: z.enum(['draft', 'published', 'archived']).default('draft'),
        featured: z.boolean().default(false),
        publishDate: z.coerce.date(),
        updatedDate: optionalDate,

        // The public author is always TekkTech, whatever is entered.
        author: z
          .unknown()
          .optional()
          .transform(() => author.name),

        image: z.preprocess(blankToUndefined, image().optional()),
        imageAlt: optionalText,
        imageCaption: optionalText,
        imageCredit: optionalText,
        imageIsAiGenerated: z.boolean().default(false),

        seoTitle: z.preprocess(blankToUndefined, z.string().trim().max(70).optional()),
        seoDescription: z.preprocess(blankToUndefined, z.string().trim().max(170).optional()),
        canonicalUrl: optionalUrl,
        socialImage: z.preprocess(blankToUndefined, image().optional()),

        sources: z.preprocess((value) => value ?? [], z.array(sourceSchema).default([])),
        related: textList,

        review: z.preprocess(emptyReviewToUndefined, reviewSchema.optional()),
        affiliateLinks: z.preprocess((value) => value ?? [], z.array(affiliateLinkSchema).default([])),
        affiliateDisclosure: z.boolean().default(false),
        sponsored: z.boolean().default(false),
        sponsorName: optionalText,

        /** Demonstration content: shown with a banner, noindexed, and easy to remove. */
        demo: z.boolean().default(false),
      })
      .superRefine((data, ctx) => {
        if (data.image && !data.imageAlt) {
          ctx.addIssue({
            code: 'custom',
            path: ['imageAlt'],
            message: 'Add alternative text describing the featured image',
          });
        }
        if (data.updatedDate && data.updatedDate < data.publishDate) {
          ctx.addIssue({
            code: 'custom',
            path: ['updatedDate'],
            message: 'The updated date cannot be earlier than the publication date',
          });
        }
        if (data.sponsored && !data.sponsorName) {
          ctx.addIssue({
            code: 'custom',
            path: ['sponsorName'],
            message: 'Sponsored articles must name the sponsor',
          });
        }
        if (data.type === 'review' && !data.review) {
          ctx.addIssue({
            code: 'custom',
            path: ['review'],
            message: 'Reviews need the review details section (at least the product name)',
          });
        }
      }),
});

const pages = defineCollection({
  loader: glob({ pattern: '**/*.md', base: './src/content/pages' }),
  schema: z.object({
    title: z.string().trim().min(2),
    description: z.string().trim().min(20).max(170),
    updatedDate: optionalDate,
    /** Marks policy pages that still need the owner's legal review. */
    requiresReview: z.boolean().default(false),
    noindex: z.boolean().default(false),
  }),
});

export const collections = { articles, pages };
